package net.j5os.chaoscontrol;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.*;import android.view.*;import java.util.*;
public class AudioActivity extends Activity{
 LinearLayout body,list; TextView status; Handler h=new Handler(Looper.getMainLooper()); int oldSize=-1; final Runnable tick=new Runnable(){public void run(){refresh();h.postDelayed(this,1000);}};
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(0xffffb74d);body.addView(b);b.setOnClickListener(v->r.run());}
 void cmd(String s){AudioService.send(this,s);}
 void value(String s,int n){startForegroundService(new Intent(this,AudioService.class).setAction(s).putExtra("value",n));}
 public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(0xff19110a);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(16,16,16,16);sc.addView(body);setContentView(sc);status=new TextView(this);status.setTextColor(0xffffb74d);status.setTextSize(22);body.addView(status);btn("Playlist • dosya ekle",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),21));btn("Oynat / Duraklat",()->cmd("play"));btn("Önceki",()->cmd("prev"));btn("Sonraki",()->cmd("next"));btn("Durdur",()->cmd("stop"));btn("Karışık çalma",()->cmd("shuffle"));btn("Tekrar",()->cmd("repeat"));btn("Ek ses desteği",()->cmd("auto"));btn("Volume Boost %100",()->value("gain",100));btn("Volume Boost %150",()->value("gain",150));btn("Volume Boost %200",()->value("gain",200));btn("Bass Boost",()->value("bass",500));btn("Normal sese dön",()->cmd("reset"));btn("Playlist temizle",()->new AlertDialog.Builder(this).setTitle("Playlist temizlensin mi?").setNegativeButton("İptal",null).setPositiveButton("Temizle",(d,w)->cmd("clear")).show());btn("Ana menü",()->finish());list=new LinearLayout(this);list.setOrientation(1);body.addView(list);cmd("init");if("add".equals(getIntent().getStringExtra("quick")))startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),21);}
 void refresh(){AudioService a=AudioService.instance;if(a==null){status.setText("CHAOS SOUNDBOARD • Durdu");return;}status.setText("CHAOS SOUNDBOARD\n"+a.title()+"\n"+a.status+" • %"+a.gain+" • Bass "+a.base/10+"%\nTekrar "+a.repeat+" • Karışık "+a.shuffle);if(oldSize!=a.tracks.size()){oldSize=a.tracks.size();list.removeAllViews();for(int j=0;j<a.tracks.size();j++){final int n=j;Button b=new Button(this);String name=a.tracks.get(j);try(android.database.Cursor c=getContentResolver().query(Uri.parse(name),new String[]{"_display_name"},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}b.setText(name);list.addView(b);b.setOnClickListener(v->startForegroundService(new Intent(this,AudioService.class).setAction("select").putExtra("index",n)));}}}
 protected void onActivityResult(int r,int c,Intent i){super.onActivityResult(r,c,i);if(r!=21||c!=RESULT_OK||i==null)return;ArrayList<String> uris=new ArrayList<>();if(i.getClipData()!=null){for(int j=0;j<i.getClipData().getItemCount();j++)add(i.getClipData().getItemAt(j).getUri(),uris);}else if(i.getData()!=null)add(i.getData(),uris);startForegroundService(new Intent(this,AudioService.class).setAction("add").putStringArrayListExtra("uris",uris));oldSize=-1;}
 void add(Uri u,ArrayList<String> a){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);a.add(u.toString());}catch(Exception e){Toast.makeText(this,"Dosya izni alınamadı",0).show();}}
 protected void onResume(){super.onResume();h.post(tick);}protected void onPause(){h.removeCallbacks(tick);super.onPause();}
}
